                                    List<StaticParam> staticParams,
                                    List<Param> params,
                                    Option<Type> returnType,
                                    Option<List<Type>> throwsC,
                                    Option<WhereClause> whereC,
                                    Option<Contract> contract) {
        IdOrOp unambiguousName;
